-- P04/P05/P07: substitui somente o recálculo de idades, gerações e seu cruzamento com distância.
-- Preserva PDF, totais, coortes e comparativos anteriores; usa coletas novas e notas explícitas.
WITH anterior AS(SELECT result->'rows'->0->'payload' AS payload FROM estudo.notebook_runs WHERE id=86 AND frozen AND status='ok' AND NOT truncated),
fontes AS(SELECT n.id AS run_id,n.cell_id,n.cell_version,r FROM estudo.notebook_runs n CROSS JOIN LATERAL jsonb_array_elements(n.result->'rows') r WHERE ((n.id=88 AND n.cell_id=295 AND n.cell_version=1) OR (n.id=89 AND n.cell_id=296 AND n.cell_version=1) OR (n.id=87 AND n.cell_id=294 AND n.cell_version=1)) AND n.frozen AND n.status='ok' AND NOT n.truncated AND n.row_count=156),
mapa AS(SELECT *,CASE r->>'bloco'
 WHEN 'idade' THEN 'idades_'||(r->>'sexo')
 WHEN 'origem' THEN 'qualidade_idades_'||(r->>'sexo')
 WHEN 'geracao' THEN 'geracoes_'||(r->>'ano')||'_'||(r->>'sexo')
 WHEN 'geracao_na_distancia' THEN 'geracao_dentro_distancia_'||(r->>'distancia')
 WHEN 'distancia_na_geracao' THEN 'distancia_dentro_geracao_'||(r->>'categoria') END AS serie,
 CASE WHEN r->>'bloco'='distancia_na_geracao' THEN r->>'distancia' ELSE r->>'categoria' END AS categoria
 FROM fontes WHERE r->>'bloco'='geracao' OR (r->>'ano')::integer=2025),
novas AS(SELECT jsonb_build_object('serie',serie,'categoria',categoria,'status','notebook_em_conciliacao','atual',jsonb_build_object('valor',r->'percentual','contagem',r->'total','denominador',r->'denominador')||jsonb_build_object('fonte','Notebook · #'||run_id||' · célula '||cell_id||' rev'||cell_version||' · 01/10/2026','nota','Regra 31/12 v1; base inclui ausentes/ambíguos/menores; população e coleta próprias')) AS item FROM mapa
 WHERE serie IN(SELECT jsonb_array_elements_text('["distancia_dentro_geracao_Alfa", "distancia_dentro_geracao_Anteriores a 1946", "distancia_dentro_geracao_Boomers", "distancia_dentro_geracao_Geração X", "distancia_dentro_geracao_Geração Z", "distancia_dentro_geracao_Millennials", "geracao_dentro_distancia_+30 km", "geracao_dentro_distancia_11 a 29 km", "geracao_dentro_distancia_6 a 10 km", "geracao_dentro_distancia_Até 5 km", "geracoes_2023_geral", "geracoes_2024_F", "geracoes_2024_M", "geracoes_2024_geral", "geracoes_2025_F", "geracoes_2025_M", "geracoes_2025_geral", "idades_F", "idades_M", "idades_geral", "qualidade_idades_F", "qualidade_idades_M", "qualidade_idades_geral"]'::jsonb)) AND r->>'percentual' IS NOT NULL),
